            int exprOn = SECOND;
            final StringTokenizer exprsTok = new StringTokenizer(expression, " \t", false);
            while (exprsTok.hasMoreTokens() && exprOn <= YEAR) {
                final String expr = exprsTok.nextToken().trim();
