    private void compatibleSharedConfigs(List<Config> configList) {
        if (null != this.getSharedConfigs()) {
            configList.addAll(this.getSharedConfigs());
        }
        List<Config> result = new ArrayList<>();
        configList.stream().collect(Collectors.groupingBy(cfg -> (cfg.getGroup() + cfg.getDataId()), LinkedHashMap::new, Collectors.toList())).forEach((key, list) -> list.stream().reduce((a, b) -> new Config(a.getDataId(), a.getGroup(), a.isRefresh() || (b != null && b.isRefresh()))).ifPresent(result::add));
        this.setSharedConfigs(result);
    }

