package com.alibaba.druid.util;

public final class HexBin {

    private static final int BASE_LENGTH = 128;

    private static final int LOOKUP_LENGTH = 16;

    private static final byte[] HEX_NUMBER_TABLE = new byte[BASE_LENGTH];

    private static final char[] UPPER_CHARS = new char[LOOKUP_LENGTH];

    private static final char[] LOWER_CHARS = new char[LOOKUP_LENGTH];

    static {
        for (int i = 0; i < BASE_LENGTH; i++) {
            HEX_NUMBER_TABLE[i] = -1;
        }
        for (int i = '9'; i >= '0'; i--) {
            HEX_NUMBER_TABLE[i] = (byte) (i - '0');
        }
        for (int i = 'F'; i >= 'A'; i--) {
            HEX_NUMBER_TABLE[i] = (byte) (i - 'A' + 10);
        }
        for (int i = 'f'; i >= 'a'; i--) {
            HEX_NUMBER_TABLE[i] = (byte) (i - 'a' + 10);
        }
        for (int i = 0; i < 10; i++) {
            UPPER_CHARS[i] = (char) ('0' + i);
            LOWER_CHARS[i] = (char) ('0' + i);
        }
        for (int i = 10; i <= 15; i++) {
            UPPER_CHARS[i] = (char) ('A' + i - 10);
            LOWER_CHARS[i] = (char) ('a' + i - 10);
        }
    }

    public static String encode(byte[] bytes);

    public static String encode(byte[] bytes, boolean upperCase);

    public static byte[] decode(String encoded);
}

